begin;
select no_plan();
insert into auth.users(id,email) values
 ('00000000-0000-4000-8000-000000005201','operator@test.invalid'),
 ('00000000-0000-4000-8000-000000005202','parent@test.invalid'),
 ('00000000-0000-4000-8000-000000005203','other-operator@test.invalid');
insert into public.operations_members(user_id,role,expires_at) values('00000000-0000-4000-8000-000000005201','finance',now()+interval '1 day'),('00000000-0000-4000-8000-000000005203','finance',now()+interval '1 day');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000005201','Reconcile Family','00000000-0000-4000-8000-000000005202');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000005201','00000000-0000-4000-8000-000000005202');
insert into public.store_subscriptions(id,family_id,platform,product_id,plan,store_key,status,expires_at,raw) values('20000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','apple','gina_plus_monthly','plus','SECRET_TOKEN','active',now()+interval '1 day','{"version":100,"private":"SECRET"}');
create function pg_temp.state(version int default 200) returns jsonb language sql as $$select jsonb_build_object('platform','apple','storeKey','SECRET_TOKEN','productId','gina_plus_monthly','status','expired','expiresAt',now()-interval '1 hour','autoRenewing',false,'accountToken','10000000-0000-4000-8000-000000005201','version',version,'raw','{}'::jsonb);$$;
-- Tests
select ok(not has_function_privilege('anon','public.finance_request_reconcile(uuid,uuid,uuid,text)','execute'),'anonymous denied');
select ok(not has_function_privilege('authenticated','public.claim_operator_reconcile(uuid)','execute'),'client cannot obtain store keys or leases');
select ok(not has_function_privilege('authenticated','public.finish_operator_reconcile(uuid,uuid,jsonb,text)','execute'),'client cannot assert verified state');
select ok(not has_table_privilege('authenticated','gina.store_reconcile_jobs','select'),'private job table inaccessible');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005202","role":"authenticated","gina":{"role":"parent"}}',true);
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Support request')$$,'42501','forbidden','parent cannot enqueue');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select is(public.finance_request_reconcile('30000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Support request')->>'status','queued','live finance operator queues');
select is(public.finance_request_reconcile('30000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Support request')->>'status','queued','enqueue replay');
select ok(position('SECRET' in public.finance_reconcile_jobs('10000000-0000-4000-8000-000000005201')::text)=0,'family history redacts tokens and payload');
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Changed')$$,'P0001','request_conflict','same command cannot change reason');
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005202','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Support request')$$,'P0001','reconcile_pending','parallel new command blocked');
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005202','10000000-0000-4000-8000-000000005299','20000000-0000-4000-8000-000000005201','Support request')$$,'P0001','subscription_not_found','family and subscription must match');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.claim',public.claim_operator_reconcile('30000000-0000-4000-8000-000000005201')::text,true);
select is(current_setting('test.claim')::jsonb->>'status','claimed','worker claims');
select is(public.claim_operator_reconcile('30000000-0000-4000-8000-000000005201')->>'status','busy','second worker does not read twice');
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005201',gen_random_uuid(),pg_temp.state())$$,'P0001','reconcile_lease_lost','foreign lease denied');
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005201',(current_setting('test.claim')::jsonb->>'token')::uuid,pg_temp.state()||'{"storeKey":"OTHER"}')$$,'P0001','account_mismatch','wrong purchase denied');
select is(public.finish_operator_reconcile('30000000-0000-4000-8000-000000005201',(current_setting('test.claim')::jsonb->>'token')::uuid,pg_temp.state())->>'status','succeeded','verified update and completion succeed');
select is((select status::text from public.store_subscriptions where store_key='SECRET_TOKEN'),'expired','entitlement updated atomically');
select is(public.claim_operator_reconcile('30000000-0000-4000-8000-000000005201')->>'status','done','completed job not reclaimed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select is(public.finance_request_reconcile('30000000-0000-4000-8000-000000005201','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Support request')->>'status','succeeded','lost response replays terminal receipt');
select public.finance_request_reconcile('30000000-0000-4000-8000-000000005202','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Check again');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.claim2',public.claim_operator_reconcile('30000000-0000-4000-8000-000000005202')::text,true);
select is(public.finish_operator_reconcile('30000000-0000-4000-8000-000000005202',(current_setting('test.claim2')::jsonb->>'token')::uuid,pg_temp.state(150))->>'status','unchanged','stale store observation not falsely counted as update');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select public.finance_request_reconcile('30000000-0000-4000-8000-000000005203','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Interrupted request');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.claim3',public.claim_operator_reconcile('30000000-0000-4000-8000-000000005203')::text,true);
reset role;
update gina.store_reconcile_jobs set lease_until=now()-interval '1 second' where id='30000000-0000-4000-8000-000000005203';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005203","role":"authenticated","gina":{"role":"none"}}',true);
select is(public.finance_request_reconcile('30000000-0000-4000-8000-000000005204','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Recover abandoned job')->>'status','queued','another live operator can recover abandoned job');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005203',(current_setting('test.claim3')::jsonb->>'token')::uuid,pg_temp.state(300))$$,'P0001','reconcile_lease_lost','superseded worker cannot mutate state');
select is((select raw->>'version' from public.store_subscriptions where store_key='SECRET_TOKEN'),'200','late worker did not change entitlement');
select set_config('test.claim4',public.claim_operator_reconcile('30000000-0000-4000-8000-000000005204')::text,true);
select is(public.finish_operator_reconcile('30000000-0000-4000-8000-000000005204',(current_setting('test.claim4')::jsonb->>'token')::uuid,null,'store_not_configured')->>'status','failed','missing provider not success');
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005204',(current_setting('test.claim4')::jsonb->>'token')::uuid,null,'provider_failed')$$,'P0001','reconcile_lease_lost','finished receipt cannot be overwritten');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select public.finance_request_reconcile('30000000-0000-4000-8000-000000005205','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Atomic completion test');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('test.claim5',public.claim_operator_reconcile('30000000-0000-4000-8000-000000005205')::text,true);
reset role;
create function pg_temp.fail_job_completion() returns trigger language plpgsql as $$begin if new.status='succeeded' then raise exception 'simulated_job_write_failure';end if;return new;end;$$;
create trigger test_job_failure before update on gina.store_reconcile_jobs for each row execute function pg_temp.fail_job_completion();
set local role service_role;
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005205',(current_setting('test.claim5')::jsonb->>'token')::uuid,pg_temp.state(300))$$,'P0001','simulated_job_write_failure','job failure rolls back entitlement write');
select is((select raw->>'version' from public.store_subscriptions where store_key='SECRET_TOKEN'),'200','no partial entitlement update on failed completion');
reset role;
drop trigger test_job_failure on gina.store_reconcile_jobs;
set local role service_role;
select throws_ok($$select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005205',(current_setting('test.claim5')::jsonb->>'token')::uuid,null,'RAW PRIVATE ERROR')$$,'22023','invalid_input','unbounded private errors cannot be stored');
select public.finish_operator_reconcile('30000000-0000-4000-8000-000000005205',(current_setting('test.claim5')::jsonb->>'token')::uuid,null,'provider_failed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005206','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Sixth check')$$,'P0001','reconcile_rate_limit','per-purchase rate limit survives new request IDs');
reset role;
update public.operations_members set revoked_at=now() where user_id='00000000-0000-4000-8000-000000005203';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005201","role":"authenticated","gina":{"role":"none"}}',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005203","role":"authenticated","gina":{"role":"none"}}',true);
select throws_ok($$select public.finance_reconcile_jobs('10000000-0000-4000-8000-000000005201')$$,'42501','forbidden','same JWT denied immediately after role revoke');
select throws_ok($$select public.finance_request_reconcile('30000000-0000-4000-8000-000000005204','10000000-0000-4000-8000-000000005201','20000000-0000-4000-8000-000000005201','Recover abandoned job')$$,'42501','forbidden','revoked operator cannot replay');
select * from finish();rollback;
